import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "../styles/global.css";

function AddComplaint() {
  const navigate = useNavigate();
  const { state } = useLocation();

  const dept = state?.dept || "Department";
  const subs = state?.subs || [];

  const [form, setForm] = useState({
    category: "",
    desc: "",
    loc: "",
    emergency: false,
    img: null
  });

  const [preview, setPreview] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setPreview(true);
  };

  return (
    <div className="complaint-page">

      {/* ⭐ HEADER */}
      <div className="complaint-header">
        <button onClick={() => navigate(-1)}>← Back</button>
        <h2>{dept} Complaint</h2>
      </div>

      {/* ⭐ FORM CARD */}
      <form className="complaint-card" onSubmit={handleSubmit}>
        <h3>File Complaint</h3>

        {/* CATEGORY */}
        <label>Category</label>
        <select
          onChange={(e) => setForm({ ...form, category: e.target.value })}
        >
          <option>Select category</option>
          {subs.map((s) => (
            <option key={s}>{s}</option>
          ))}
        </select>

        {/* DESC */}
        <label>Description</label>
        <textarea
          placeholder="Explain issue"
          onChange={(e) => setForm({ ...form, desc: e.target.value })}
        />

        {/* LOCATION */}
        <label>Location</label>
        <input
          placeholder="Enter location"
          onChange={(e) => setForm({ ...form, loc: e.target.value })}
        />

        {/* EMERGENCY */}
        <label className="switch">
          <input
            type="checkbox"
            onChange={(e) =>
              setForm({ ...form, emergency: e.target.checked })
            }
          />
          <span className="slider"></span>
          Emergency
        </label>

        {/* IMAGE */}
        <label>Upload Image</label>
        <input
          type="file"
          onChange={(e) => setForm({ ...form, img: e.target.files[0] })}
        />

        <button>Preview Complaint</button>
      </form>

      {/* ⭐ PREVIEW MODAL */}
      {preview && (
        <div className="modal">
          <div className="modal-card">
            <h3>Complaint Preview</h3>
            <p><b>Dept:</b> {dept}</p>
            <p><b>Category:</b> {form.category}</p>
            <p><b>Desc:</b> {form.desc}</p>
            <p><b>Location:</b> {form.loc}</p>
            <p><b>Emergency:</b> {form.emergency ? "Yes" : "No"}</p>

            <button onClick={() => setPreview(false)}>Edit</button>
            <button className="submit">Submit</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default AddComplaint;
